import { getCurrentWindow } from "@tauri-apps/api/window";
import { useEffect, type ReactNode, type SVGProps } from "react";
import { Button } from "../../components/Button";
import { useI18n } from "../../i18n/i18n";
import {
  HOTKEY_HOME_ROUTE_PATH,
  openInHotkeyWindow,
  openInMainWindow,
} from "../../services/windowNavigation";

const HOTKEY_DETAIL_TITLE_LEFT = 64;
const HOTKEY_DETAIL_TITLE_RIGHT = 96;
const HOTKEY_DETAIL_ACTION_OFFSET = 12;

export function HotkeyWindowDetailLayout({
  canCollapseToHome = true,
  children,
  mainWindowPath,
  title,
}: {
  canCollapseToHome?: boolean;
  children: ReactNode;
  mainWindowPath: string;
  title: ReactNode;
}) {
  const { t } = useI18n();

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (
        event.key !== "Escape" ||
        event.defaultPrevented ||
        event.metaKey ||
        event.ctrlKey ||
        event.altKey ||
        event.shiftKey
      ) {
        return;
      }

      event.preventDefault();
      event.stopPropagation();
      hideCurrentWindow();
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => {
      window.removeEventListener("keydown", handleKeyDown);
    };
  }, []);

  return (
    <div className="flex h-full w-full flex-col overflow-hidden rounded-2xl border border-token-border-light bg-token-main-surface-primary">
      <div className="draggable relative flex h-toolbar-sm items-center justify-center px-3">
        <div className="absolute inset-y-0 flex items-center gap-0" style={{ left: HOTKEY_DETAIL_ACTION_OFFSET }}>
          <Button
            aria-label={t("hotkeyWindow.dismiss")}
            color="ghost"
            size="toolbar"
            title={t("hotkeyWindow.dismiss")}
            uniform
            onClick={() => {
              hideCurrentWindow();
            }}
          >
            <HotkeyDismissIcon className="icon-xs" />
          </Button>
        </div>

        <div
          className="absolute inset-y-0 flex items-center justify-center text-base font-medium text-token-foreground/60 select-none"
          style={{ left: HOTKEY_DETAIL_TITLE_LEFT, right: HOTKEY_DETAIL_TITLE_RIGHT }}
        >
          {title}
        </div>

        <div className="absolute flex items-center gap-0" style={{ right: HOTKEY_DETAIL_ACTION_OFFSET }}>
          {canCollapseToHome ? (
            <Button
              aria-label={t("hotkeyWindow.threadPage.newButton")}
              color="ghost"
              size="toolbar"
              title={t("hotkeyWindow.threadPage.newButton")}
              uniform
              onClick={() => {
                void openInHotkeyWindow(HOTKEY_HOME_ROUTE_PATH).catch(() => undefined);
              }}
            >
              <HotkeyNewThreadIcon className="icon-sm" />
            </Button>
          ) : null}
          <Button
            aria-label={t("hotkeyWindow.threadPage.openInMainWindow")}
            color="ghost"
            size="toolbar"
            title={t("hotkeyWindow.threadPage.openInMainWindow")}
            uniform
            onClick={() => {
              void openInMainWindow(mainWindowPath).catch(() => undefined);
            }}
          >
            <HotkeyOpenInMainWindowIcon className="icon-sm" />
          </Button>
        </div>
      </div>

      <div className="min-h-0 flex-1">{children}</div>
    </div>
  );
}

function hideCurrentWindow() {
  const currentWindow = getHotkeyWindow();
  if (currentWindow === null) {
    return;
  }

  void currentWindow.hide().catch(() => undefined);
}

function getHotkeyWindow() {
  if (
    typeof window === "undefined" ||
    typeof window !== "object" ||
    !("__TAURI_INTERNALS__" in window)
  ) {
    return null;
  }

  return getCurrentWindow();
}

